import os
import json
from typing import Any, Dict, List, Optional, Union

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def extract_layout_from_document(
    document: Union[str, bytes],
    *,
    model_id: str = "prebuilt-layout",
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract layout elements (blocks/paragraphs, lines, tables) from a document using
    Azure AI Document Intelligence.

    Args:
        document: Path to a local file, raw bytes, or a file-like object with .read().
        model_id: Document Intelligence model to use; defaults to "prebuilt-layout".
        endpoint: Azure Document Intelligence endpoint. Falls back to
            AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT.
        api_key: Azure Document Intelligence key. Falls back to
            AZURE_DOCUMENT_INTELLIGENCE_KEY.

    Returns:
        A dictionary containing extracted layout elements.
    """
    endpoint = endpoint or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = api_key or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint:
        raise ValueError("Missing Azure Document Intelligence endpoint.")
    if not api_key:
        raise ValueError("Missing Azure Document Intelligence key.")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))

    file_handle = None
    try:
        if isinstance(document, str):
            file_handle = open(document, "rb")
            stream = file_handle
        else:
            stream = document

        poller = client.begin_analyze_document(model_id=model_id, analyze_request=stream)
        result = poller.result()

        def _span_to_dict(span: Any) -> Dict[str, Any]:
            return {
                "offset": getattr(span, "offset", None),
                "length": getattr(span, "length", None),
            }

        def _polygon_to_list(polygon: Any) -> List[float]:
            if polygon is None:
                return []
            try:
                return [float(v) for v in polygon]
            except TypeError:
                return []

        paragraphs: List[Dict[str, Any]] = []
        for p in getattr(result, "paragraphs", []) or []:
            paragraphs.append(
                {
                    "role": getattr(p, "role", None),
                    "content": getattr(p, "content", None),
                    "bounding_regions": [
                        {
                            "page_number": getattr(br, "page_number", None),
                            "polygon": _polygon_to_list(getattr(br, "polygon", None)),
                        }
                        for br in (getattr(p, "bounding_regions", []) or [])
                    ],
                    "spans": [_span_to_dict(s) for s in (getattr(p, "spans", []) or [])],
                }
            )

        lines: List[Dict[str, Any]] = []
        pages = getattr(result, "pages", []) or []
        for page in pages:
            for line in getattr(page, "lines", []) or []:
                lines.append(
                    {
                        "page_number": getattr(page, "page_number", None),
                        "content": getattr(line, "content", None),
                        "polygon": _polygon_to_list(getattr(line, "polygon", None)),
                        "spans": [_span_to_dict(s) for s in (getattr(line, "spans", []) or [])],
                    }
                )

        tables: List[Dict[str, Any]] = []
        for t in getattr(result, "tables", []) or []:
            cells: List[Dict[str, Any]] = []
            for cell in getattr(t, "cells", []) or []:
                cells.append(
                    {
                        "row_index": getattr(cell, "row_index", None),
                        "column_index": getattr(cell, "column_index", None),
                        "row_span": getattr(cell, "row_span", None),
                        "column_span": getattr(cell, "column_span", None),
                        "kind": getattr(cell, "kind", None),
                        "content": getattr(cell, "content", None),
                        "polygon": _polygon_to_list(getattr(cell, "polygon", None)),
                    }
                )

            tables.append(
                {
                    "row_count": getattr(t, "row_count", None),
                    "column_count": getattr(t, "column_count", None),
                    "bounding_regions": [
                        {
                            "page_number": getattr(br, "page_number", None),
                            "polygon": _polygon_to_list(getattr(br, "polygon", None)),
                        }
                        for br in (getattr(t, "bounding_regions", []) or [])
                    ],
                    "cells": cells,
                }
            )

        doc_content = getattr(result, "content", None)

        return {
            "content": doc_content,
            "pages": [
                {
                    "page_number": getattr(page, "page_number", None),
                    "width": getattr(page, "width", None),
                    "height": getattr(page, "height", None),
                    "unit": getattr(page, "unit", None),
                    "angle": getattr(page, "angle", None),
                }
                for page in pages
            ],
            "paragraphs": paragraphs,
            "lines": lines,
            "tables": tables,
        }
    finally:
        if file_handle is not None:
            file_handle.close()


def extract_layout_from_document_json(
    document: Union[str, bytes],
    *,
    model_id: str = "prebuilt-layout",
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> str:
    """
    Convenience wrapper that returns extracted layout as a JSON string.
    """
    return json.dumps(
        extract_layout_from_document(
            document=document,
            model_id=model_id,
            endpoint=endpoint,
            api_key=api_key,
        ),
        ensure_ascii=False,
        indent=2,
        default=str,
    )
